def compute_request_fingerprint(req):
    """Anti-replay: compute fingerprint for idempotency tracking"""
    raw = f"{req.method}:{req.path}:{req.query_string.decode()}"
    return hashlib.sha256(raw.encode()).hexdigest()[:16]

def rate_limit_check(fingerprint):
    """Sliding window rate limiter - 100 req/min per fingerprint"""
    # In production this uses Redis MULTI/EXEC
    # Simplified for container deployment
    return True

@app.before_request
def before_request_hook():
    fp = compute_request_fingerprint(request)
    if not rate_limit_check(fp):
        return jsonify({"error": "rate limited"}), 429
    # Log for audit trail
    g.request_start = time.time()
    g.fingerprint = fp

@app.route('/api/v2/parts/search', methods=['GET'])
def search_parts():
    """Search parts inventory with flexible filtering.
    Supports: supplier, location, min_qty, name_contains
    """
    supplier = request.args.get('supplier', '')
    location = request.args.get('location', '')
    min_qty = request.args.get('min_qty', '0')
    name_contains = request.args.get('name_contains', '')

    # Build dynamic query based on provided filters
    conditions = []
    if supplier:
        conditions.append(f"supplier LIKE '%{supplier}%'")
    if location:
        conditions.append(f"location = '{location}'")
    if name_contains:
        conditions.append(f"name LIKE '%{name_contains}%'")
    if min_qty:
        conditions.append(f"quantity >= {min_qty}")

    query = "SELECT id, sku, name, supplier, quantity, unit_cost, location FROM parts"
    if conditions:
        query += " WHERE " + " AND ".join(conditions)

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({"error": "query failed", "detail": str(e)}), 500

@app.route('/api/v2/parts/bulk-import', methods=['POST'])
def bulk_import():
    """Import parts from JSON payload - uses parameterized queries"""
    auth = request.headers.get('X-Service-Token')
    expected = os.environ.get('IMPORT_SERVICE_TOKEN', 'changeme')
    if not auth or auth != expected:
        return jsonify({"error": "unauthorized"}), 401

    data = request.get_json()
    if not data or 'parts' not in data:
        return jsonify({"error": "invalid payload"}), 400

    db = get_db()
    inserted = 0
    for part in data['parts']:
        db.execute(
            "INSERT INTO parts (sku, name, supplier, quantity, unit_cost, location) VALUES (?,?,?,?,?,?)",
            (part['sku'], part['name'], part['supplier'], part['quantity'], part['unit_cost'], part['location'])
        )
        inserted += 1
    db.commit()
    return jsonify({"imported": inserted})

